342	              overflow: TextOverflow.ellipsis,
343	            ),
344	            const SizedBox(height: DesignTokens.spacingXs / 2),
345	            Text(
346	              timestampLabel,
347	              style: DesignTokens.textMonoCaption.copyWith(color: DesignTokens.colorTextSecondary),
348	            ),
349	          ],
350	        ),
351	      ),
352	    );
353	  }
354	}
