356	/// There is no `name` field anywhere yet — the account's email (decoded
357	/// from the stored access token's own JWT, [SecureTokenStorage.readAccountEmail])
358	/// is the only real identity this app has on-device. Both derive from its
359	/// local-part (before `@`), split on `.`/`_`/`-`: "wagner.duarte@x.com" ->
360	/// name "Wagner Duarte", initials "WD". A real display name belongs to the
361	/// Configurações unit (prototype: "avatar with editable name/e-mail") —
362	/// this is a stand-in until that unit wires one in.
363	List<String> _emailNameWords(String email) => email
364	    .split('@')
365	    .first
366	    .split(RegExp(r'[._-]+'))
367	    .where((w) => w.isNotEmpty)
368	    .toList();
369	
370	String _displayNameFromEmail(String email) {
371	  final words = _emailNameWords(email);
372	  if (words.isEmpty) return email;
373	  return words.map((w) => '${w[0].toUpperCase()}${w.substring(1)}').join(' ');
374	}
375	
376	String _initialsFromEmail(String email) {
377	  final words = _emailNameWords(email);
378	  if (words.isEmpty) return '?';
379	  if (words.length == 1) return words.first.substring(0, 1).toUpperCase();
380	  return (words[0].substring(0, 1) + words[1].substring(0, 1)).toUpperCase();
381	}
